INSERT INTO `events` VALUES (35,'Electric Symphony Live: Neo-Classical Concert','electric-symphony-live','An immersive orchestral experience combining a 60-piece philharmonic orchestra with modular synthesizers and responsive laser mapping. Feat. compositions from world-renowned cinematic soundtrack artists.',54,'Grand Arena Hall','700 Arena Way, Austin, TX 78701','2026-11-05 03:01:09','2026-11-05 06:31:09',1299.00,'INR',500,496,'PUBLISHED',30,'2026-10-14 07:31:09','2026-10-17 19:31:20'),(36,'World Esports Championship Finals','world-esports-championship-finals','Witness the world\'s elite esports contenders clash for the multimillion-dollar grand championship prize in front of 15,000 roaring fans with live caster analysis and high-stakes tournament brackets.',113,'Olympic Indoor Stadium','1000 Champions Boulevard, Los Angeles, CA 90015','2026-11-13 23:31:09','2026-11-15 05:31:09',899.00,'INR',800,800,'PUBLISHED',30,'2026-10-14 07:31:09','2026-10-14 08:30:52'),(37,'Modern Minimalist Design & UX Conference','modern-minimalist-design-ux-conference','Explore the bleeding edge of design systems, accessibility tokens, and interactive micro-animations. Hands-on workshops led by design directors from leading design studios.',111,'Metro Exhibition Pavilion','450 5th Avenue, New York, NY 10018','2026-11-23 17:31:09','2026-11-25 00:31:09',1499.00,'INR',150,150,'PUBLISHED',30,'2026-10-14 07:31:09','2026-10-14 08:30:52'),(38,'Sunset Rooftop Jazz & Wine Festival','sunset-rooftop-jazz-wine-festival','Enjoy a curated selection of artisan vintages paired with smooth live acoustic jazz ensembles overlooking the panoramic city skyline at twilight.',54,'Skyline Terrace Gardens','200 Harbor Drive, San Diego, CA 92101','2026-10-22 01:31:09','2026-10-22 06:01:09',1899.00,'INR',100,89,'PUBLISHED',30,'2026-10-14 07:31:09','2026-10-18 13:57:49'),(39,'Contemporary Urban Arts Biennial','contemporary-urban-arts-biennial','A vibrant public exhibition presenting monumental outdoor sculptures, interactive audiovisual installations, and dynamic mural showcases from over 40 emerging international artists.',56,'Downtown Culture Center','320 S Michigan Ave, Chicago, IL 60604','2026-11-16 16:56:05','2026-11-23 01:56:05',499.00,'INR',300,280,'PUBLISHED',82066610,'2026-10-14 07:31:09','2026-10-19 05:56:05'),(12394211,'Sunburn Arena EDM Night 2026 - Mumbai','sunburn-arena-edm-night-2026-mumbai-past','A colossal electronic dance music night featuring international headliners and arena-scale soundscapes.',54,'MMRDA Grounds','Bandra Kurla Complex, Mumbai, Maharashtra 400051','2026-10-01 19:00:00','2026-10-01 23:30:00',1499.00,'INR',5000,0,'PUBLISHED',30,'2026-10-17 08:41:03','2026-10-17 08:42:59'),(12703554,'Bengaluru Heritage Food & Craft Beer Fiesta','bengaluru-heritage-food-craft-beer-past','An artisanal culinary weekend featuring 40+ master chefs, regional delicacies, and micro-breweries.',114,'Jaymahal Palace Hotel Gardens','1 Jayamahal Road, Bengaluru, Karnataka 560046','2026-10-10 12:00:00','2026-10-10 22:00:00',799.00,'INR',2000,0,'PUBLISHED',30,'2026-10-17 08:41:03','2026-10-17 08:42:59'),(15754745,'Global Tech & AI Summit 2026','global-tech-ai-summit-2026','The world\'s premier gathering of artificial intelligence researchers, distributed systems architects, and venture leaders. Keynotes from industry pioneers and technical deep-dives into LLMs, autonomous agents, and quantum computing.',111,'San Francisco Civic Center','99 Grove St, San Francisco, CA 94102','2026-11-02 14:56:05','2026-11-04 23:56:05',2499.00,'INR',500,485,'PUBLISHED',82066610,'2026-10-17 11:12:40','2026-10-19 05:56:05'),(21505232,'Great Indian Food & Craft Beer Fiesta — Pune','great-indian-food-craft-beer-fiesta-pune','Over 80 gourmet food popups, regional barbecues, award-winning microbreweries, masterchef live cook-offs, and live indie-rock band sets.',114,'Mahalaxmi Lawns','Karve Nagar, Pune, Maharashtra 411052','2026-10-28 22:19:48','2026-10-30 08:19:48',599.00,'INR',3000,2750,'PUBLISHE