  `seat_label` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'General Admission',
  `status` enum('ACTIVE','CHECKED_IN','CANCELLED','REVOKED','EXPIRED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
